        if dist_sq(p, C) > r2:
            # Update radius
            r2 = dist_sq(p, C)
            C = p

    # Iterative refinement to minimize maximum distance
    for _ in range(200):
        new_C = [0.0, 0.0, 0.0]
        max_d2 = -1

        for p in points:
            d2 = dist_sq(p, tuple(new_C))
            if d2 > max_d2:
                max_d2 = d2

        # Simple numerical optimization using centers of pairs and triples
        best_C = new_C
        best_max_d2 = max_d2

        # Check two-point centers (midpoints)
        for i in range(len(points)):
            for j in range(i+1, len(points)):
                mid = [
                    (points[i][0] + points[j][0]) / 2,
                    (points[i][1] + points[j][1]) / 2,
                    (points[i][2] + points[j][2]) / 2
                ]
                max_d2_pair = 0
                for p in points:
