                    # Simple closest to all three (centroid of triangle)
                    cent = [
                        (p1[0] + p2[0] + p3[0]) / 3,
                        (p1[1] + p2[1] + p3[1]) / 3,
                        (p1[2] + p2[2] + p3[2]) / 3
                    ]
                    max_d2_triple = 0
