def solution(input_text):
    """
    Correct solution for the Cycle or Independent Set problem.
    """
    from math import ceil, sqrt

    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    k = max(ceil(sqrt(n)), 3)

    # DFS cycle detection with path preservation
    def find_cycle():
        visited = {}
        parent = {}
        path = []

        def rec(u, p, depth):
            if u in visited:
                try:
                    idx = path.index(u)
                    cycle = path[idx:] + [u]
                    return cycle if len(cycle) >= k else None
                except:
                    return None

            visited[u] = True
            path.append(u)
            parent[u] = (p, depth)

            for v in adj[u]:
                if v == p:
                    continue
                result = rec(v, u, depth + 1)
                if result:
                    del path[-1]
                    del visited[u]
                    return result

            del visited[u]
            path.pop()
            return None

        for s in range(1, n + 1):
            if rec(s, -1, 0):
                return rec(s, -1, 0)
        return None

    cycle = find_cycle()
    if cycle:
        return f"2\n{len(cycle)}\n{' '.join(map(str, cycle))}\n"

    # Independent set fallback
    indep = [1]
    for v in range(2, n + 1):
        if not any(v in adj[x] for x in indep):
            indep.append(v)
        if len(indep) >= k:
            break

    return "1" + "\n" + " ".join(map(str, indep[:k])) + "\n"

