    # Segment boundaries
    segments = []
    current_segment = []

    for line in lines[1:]:
        parts = line.split()
        if parts[0] == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(parts[1])

    if current_segment:
        segments.append(current_segment)

    # Collect all unique friends
    friend_set = set()
    for seg in segments:
        friend_set.update(seg)

    friends = list(friend_set)
    m = len(friends)
    friend_to_idx = {f: i for i, f in enumerate(friends)}

    # Build conflict graph (adjacency list)
    adj = [set() for _ in range(m)]
    for seg in segments:
        for i in range(len(seg)):
            for j in range(i + 1, len(seg)):
                u = friend_to_idx[seg[i]]
                v = friend_to_idx[seg[j]]
                adj[u].add(v)
                adj[v].add(u)

    # Backtracking with pruning
    best = 0

    def backtrack(idx, current, blocked):
        nonlocal best
        best = max(best, len(current))

        # Pruning
        if best >= len(current) + (m - idx):
            return

        if idx == m:
            return

        u = idx

        # Try including friend u if not blocked
        can_include = True
        for v in current:
            if adj[u].intersection({v}):
                can_include = False
                break

        # Exclude from blocked set if we tried and failed
        if not can_include:
            if u in blocked:
                blocked.remove(u)
            backtrack(idx + 1, current.copy(), blocked if can_include else blocked)
        else:
            include_current = u not in current and all(v not in adj[u] for v in current)

            if include_current:
                current.append(u)
                current_set = set(current)
                backtrack(idx + 1, current, blocked)
                current.pop()

            # Always try excluding
            filtered_current = [v for v in current if v != u]
            backtrack(idx + 1, filtered_current, blocked)

    backtrack(0, [], set())

    return str(best)

