def can_transform(sub: str, target: str) -> bool:
    """Check if substring can be transformed to target using valid pairs."""
    letters = [97, 97]  # base
    letters = [ord(char) for char in "abcdefghijklmnopqrstuvwxyz"]  # 26 letters

    # constrained letters that match => cannot be in any pair
    matched_letters = set()
    # mapping from char -> its pair partner
    char_pairs = {}

    for s1, t1 in zip(sub, target):
        if s1 == t1:
            matched_letters.add(s1)
        else:
            c = s1
            p = t1

            # Check consistency: if c is already mapped, it must map to p
            if c in char_pairs:
                if char_pairs[c] != p:
                    return False
                # Check if p is also mapped (it must map back to c)
                if p in char_pairs:
                    if char_pairs[p] != c:
                        return False
            else:
                # Check forward mapping
                if p in char_pairs:
                    return False  # p already mapped to something else
                # Check backward mapping
                if c in char_pairs:
                    return False  # c already has another mapping
                if p == c:
                    # This shouldn't happen as s1 == t1
                    return False
                char_pairs[c] = p
                char_pairs[p] = c

    # Check: matched letters cannot be part of any pair
    for m in matched_letters:
        if m in char_pairs:
            return False

    return True

