    def get_prime_factors(n):
        factors = {}
        i = 2
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n //= i
            i += 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    def get_divisors(n):
        factors = get_prime_factors(n)
        divs = {1}
        for p, exp in factors.items():
            new_divs = set()
            for d in divs:
                temp = d
                for _ in range(exp):
                    temp *= p
                    new_divs.add(temp)
            divs.update(new_divs)
        return sorted([d for d in divs if d > 1])

