            else:
                cnt[i + 1] = cnt[i]
        prefix.append(cnt)

    def count_range(ending, l, r):
        return prefix[ending - 1][r] - prefix[ending - 1][l - 1]

    def falling2(x, k):
        return (fact[x] * inv_fact[x - k] % MOD) * inv_fact[k] % MOD if k > 0 else x % MOD

    def falling3(x, k):
        if k <= 0:
            return 1
        return (fact[x] * inv_fact[x - k] % MOD) * inv_fact[k] % MOD

    ans = []
    for l, r, k in queries:
        product = 1
        visited = set()
        total_used = 0

        for i in range(l - 1, r):
            ending = e[i]
            if ending in visited:
                continue
            visited.add(ending)
            cnt = count_range(ending, l, r)
            term = falling3(cnt + k, cnt)
            product = (product * term) % MOD
            total_used += cnt

