        Returns True if current player can force a win from state (x, y),
        False if current player will lose with optimal play by opponent
        """
        if (x, y) in memo:
            return memo[(x, y)]

        # Check if current state already violates (should not happen for valid play)
        if x ** y >= n:
            return False

        can_force_lose = False

        # Try adding a box
        if (x + 1) ** y < n:
            # If opponent loses from this new state, we win
            if not compute_winning(x + 1, y):
                can_force_lose = True

        # Try adding an item
        if not can_force_lose and x ** (y + 1) < n:
            # If opponent loses from this new state, we win
            if not compute_winning(x, y + 1):
                can_force_lose = True

        memo[(x, y)] = can_force_lose
        return can_force_lose

    # Stas goes first
    # If Stas can force a win, then Masha wins (output Masha)
    # If Stas cannot force a win, then Stas wins (output Stas)
    if compute_winning(a, b):
        return "Masha\n\n"
    else:
