from functools import lru_cache


def solution(s):
    """
    Count the number of ways to visit exactly k planets

    From planet x, we can move to any unvisited planet y where 1 <= y <= x + m
    """
    try:
        n, k, m = map(int, s.strip().split())
    except:
        return "0"

    MOD = 10**9 + 7

    if k == 1:
        return str(n)

    # You'll make k-1 moves to visit k planets
    # From current position pos, can move to any unvisited position in [1, pos + m]

    @lru_cache(maxsize=2000000)
    def dp(pos, visited, count):
        if count == k:
            return 1
        ways = 0
        max_next = min(n, pos + m)
        for next_pos in range(1, max_next + 1):
            if not (visited & (1 << next_pos)):
                ways = (ways + dp(next_pos, visited | (1 << next_pos), count + 1)) % MOD
        return ways

    total = 0
    for start in range(1, n + 1):
        total = (total + dp(start, 1 << start, 1)) % MOD

    return str(total)


