    return "YES\n" + " ".join(result)

import math

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "0.0000"

    try:
        x1, y1, x2, y2 = map(float, lines[0].split())
    except ValueError:
        return "0.0000"

    base_dist = math.hypot(x2 - x1, y2 - y1)

    try:
        n = int(lines[1].strip())
    except (IndexError, ValueError):
        n = 0

    circles = []
    if len(lines) > 2:
        for i in range(n):
            if i + 2 < len(lines):
                try:
                    xi, yi, ri = map(float, lines[i + 2].split())
                    circles.append((xi, yi, ri))
                except ValueError:
                    pass

    if n == 0:
        if base_dist == 0:
            return "0.0000"
        return str(base_dist / 2.0)

    def check(R):
        # Minimum R must be at least base_dist/2
        if R < base_dist / 2.0 - 1e-12:
            return False

        # Compute half the distance and h (distance from midpoint to center)
        R_sq = R * R
        h_sq = R_sq - (base_dist / 2.0) ** 2
        if h_sq < -1e-9:
            return False
        h = math.sqrt(max(0.0, h_sq))

        dx = x2 - x1
        dy = y2 - y1

        # Unit perpendicular vector
        if base_dist > 1e-12:
            unit_perp_x = -dy / base_dist
            unit_perp_y = dx / base_dist
        else:
            unit_perp_x = 0.0
            unit_perp_y = 1.0

        # Midpoint
        Mx = (x1 + x2) / 2.0
        My = (y1 + y2) / 2.0

        # Two possible centers symmetric about the midpoint
        c1x, c1y = Mx + h * unit_perp_x, My + h * unit_perp_y
        c2x, c2y = Mx - h * unit_perp_x, My - h * unit_perp_y

        # Check each center
        for (cx, cy) in [(c1x, c1y), (c2x, c2y)]:
            valid = True
            for (ox, oy, oradius) in circles:
                dist = math.hypot(cx - ox, cy - oy)
                # Check for intersection
                # No intersection if circle i is fully inside ours OR fully outside
                cond_inside = dist + oradius <= R + 1e-9
                cond_outside = dist >= R + oradius - 1e-9
                if not (cond_inside or cond_outside):
                    valid = False
                    break
            if valid:
                return True
        return False

    # Set search bounds
    low = base_dist / 2.0
    max_2ri = 2.0
    for *_, r in circles:
        max_2ri = max(max_2ri, 2.0 * r)
    high = max(base_dist * 3.0, max_2ri, 10**12 + 1000.0)

    # Binary search for minimum valid radius
    for _ in range(200):
        mid = (low + high) / 2.0
        if check(mid):
            high = mid
        else:
            low = mid

    return str(high)

