def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    try:
        N = int(lines[0])

        # Parse cost matrix
        costs = []
        for line in lines[1:]:
            if line.strip():
                costs.append(list(map(int, line.strip().split())))

        # Build complete N x N cost matrix
        full_costs = [[0] * N for _ in range(N)]
        for i in range(N):
            for k, val in enumerate(costs[i]):
                if k < i:
                    j = k
                else:
                    j = k + 1
                full_costs[i][j] = val

        # Build preference rankings (lower cost = better, lower rank = better)
        ranks = [[0] * N for _ in range(N)]
        for i in range(N):
            prefs = [(full_costs[i][j], j) for j in range(N) if j != i]
            prefs.sort()  # Sort by cost (lower is better)
            for rank, (_, city) in enumerate(prefs):
                ranks[i][city] = rank

        # Gale-Shapley: cities are proposers
        partner_of = [-1] * N  # partner_of[j] = which city is matched with city j
        next_proposal = [0] * N  # next index in ranks[city] to propose to
        unmatched = set(range(N))

        while unmatched:
            # Get an arbitrary unmatched city
            city = next(iter(unmatched))

            # Keep proposing until matched or exhausted
            while next_proposal[city] < N:
                j = ranks[city][next_proposal[city]]
                next_proposal[city] += 1

                if partner_of[j] == -1:
                    # j is unmatched, match them
                    partner_of[j] = city
                    partner_of[city] = j
                    unmatched.remove(city)
                    break
                else:
                    # j is matched with someone else
                    current_partner = partner_of[j]

                    # Check if city prefers j over current_partner
                    if ranks[city][j] < ranks[city][current_partner]:
                        # City prefers new proposal
                        partner_of[j] = city
                        partner_of[current_partner] = -1
                        partner_of[city] = j
                        unmatched.add(current_partner)
                        unmatched.remove(city)
                        break
                    else:
                        # City prefers current partner, keep trying
                        pass

        # Check if perfect matching was found
        for i in range(N):
            if partner_of[i] == -1:
                return '-1'

        # Build result: for each city i, output which city it's paired with
        result = []
        for i in range(N):
            result.append(str(partner_of[i]))

        return '\n'.join(result) + '\n'

    except:
        return '-1\n'

